// Payload Tally : { data: { fields: [{ label, value, type }] } }
const body = $json.body ?? $json;
const fields = body?.data?.fields ?? [];

const get = (needle) => {
  const f = fields.find((f) =>
    (f.label ?? "").toLowerCase().includes(needle)
  );
  if (!f) return "";
  // Les champs téléphone Tally peuvent renvoyer un objet ou un tableau
  if (typeof f.value === "string") return f.value;
  if (Array.isArray(f.value)) return f.value.join(", ");
  return f.value?.toString?.() ?? "";
};

const nomComplet = get("nom et prénom") || get("nom");
const [prenom, ...reste] = nomComplet.trim().split(/\s+/);

return {
  json: {
    nomComplet,
    prenom: prenom ?? "",
    nom: reste.join(" "),
    email: get("email"),
    entreprise: get("entreprise"),
    telephone: get("téléphone") || get("telephone") || get("phone"),
    recuLe: body?.createdAt ?? new Date().toISOString(),
  },
};

